using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
        // To remain compatible with existing documents, restore the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id property now maps only to the raw key by default (e.g. "1"),
        // not the old "EntityType|Key" format (e.g. "Blog|1").
        // To read existing documents with the old id format, opt back in explicitly.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.IdValueGenerator>();

        // Breaking change 3: Cosmos DB provider no longer supports client-side indexing.
        // HasIndex() now throws at model validation; remove it.
        // (HasIndex call removed — Cosmos handles indexing server-side via indexing policy.)
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

